=== WeekendPackagePlan.java
     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import hotel.rooms.RoomType;
     5	import java.math.BigDecimal;
     6	import java.time.DayOfWeek;
     7	import java.util.Map;
     8	
     9	/** Friday to the Sunday right after, for a fixed price per room type, in any season. */
    10	final class WeekendPackagePlan implements RatePlanPolicy {
    11	
    12	    private static final Map<RoomType, BigDecimal> PRICE_BY_ROOM_TYPE = Map.of(
    13	            RoomType.STANDARD, new BigDecimal("520.00"),
    14	            RoomType.DELUXE, new BigDecimal("820.00"),
    15	            RoomType.SUITE, new BigDecimal("1200.00"));
    16	    private static final BigDecimal REFUNDED_SHARE = new BigDecimal("0.5");
    17	
    18	    @Override
    19	    public void validate(Room room, NewReservation request) {
    20	        boolean fridayToSunday = request.checkIn().getDayOfWeek() == DayOfWeek.FRIDAY
    21	                && request.checkOut().equals(request.checkIn().plusDays(2));
    22	        if (!fridayToSunday) {
    23	            throw new HotelException(ErrorCode.INVALID_REQUEST,
    24	                    "the weekend package goes from a Friday to the Sunday right after");
    25	        }
    26	    }
    27	
    28	    @Override
    29	    public Price price(Room room, NewReservation request, NightlyCharges charges) {
    30	        BigDecimal packagePrice = PRICE_BY_ROOM_TYPE.get(room.type());
    31	        return new Price(charges.nights(), packagePrice, PriceCalculator.cents(BigDecimal.ZERO), packagePrice);
    32	    }
    33	
    34	    @Override
    35	    public BigDecimal refund(Reservation reservation) {
    36	        return PriceCalculator.cents(reservation.amountPaid().multiply(REFUNDED_SHARE));
    37	    }
    38	}
