344	
345	import hotel.reservations.Reservation;
346	import hotel.reservations.ReservationStore;
347	import hotel.rooms.Room;
348	import hotel.rooms.Rooms;
349	import java.time.LocalDate;
350	import java.util.ArrayList;
351	import java.util.Comparator;
352	import java.util.List;
353	
354	/** Which rooms are occupied on a given night, for the front desk (CSV). */
355	public final class OccupancyReport {
356	
357	    private final Rooms rooms;
358	    private final ReservationStore store;
359	
360	    public OccupancyReport(Rooms rooms, ReservationStore store) {
361	        this.rooms = rooms;
362	        this.store = store;
363	    }
364	
365	    public String generate(LocalDate night) {
366	        List<Reservation> occupying = new ArrayList<>();
367	        for (Reservation reservation : store.all()) {
368	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
369	            if (reservation.isPaid() && coversNight) {
370	                occupying.add(reservation);
371	            }
372	        }
373	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
374	
375	        StringBuilder csv = new StringBuilder();
376	        csv.append("room,type,reservation,check_in,check_out\n");
377	        for (Reservation reservation : occupying) {
378	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
379	            csv.append(room.number()).append(',')
380	                    .append(room.type()).append(',')
381	                    .append(reservation.id()).append(',')
382	                    .append(reservation.checkIn()).append(',')
383	                    .append(reservation.checkOut()).append('\n');
384	        }
385	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
386	        return csv.toString();
387	    }
388	}
389	package hotel.reports;
390	
391	import hotel.reservations.Reservation;
392	import hotel.reservations.ReservationStore;
393	import java.math.BigDecimal;
394	import java.time.YearMonth;
395	import java.util.ArrayList;
396	import java.util.Comparator;
397	import java.util.List;
398	
399	/**
400	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
401	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
402	 */
403	public final class RevenueReport {
404	
405	    private final ReservationStore store;
406	
407	    public RevenueReport(ReservationStore store) {
408	        this.store = store;
409	    }
410	
411	    public String generate(YearMonth month) {
412	        List<Reservation> withRevenue = new ArrayList<>();
413	        for (Reservation reservation : store.all()) {
414	            boolean keptMoney = reservation.amountKept().signum() > 0;
415	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
416	            if (keptMoney && startsInMonth) {
417	                withRevenue.add(reservation);
418	            }
419	        }
420	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
421	
422	        StringBuilder csv = new StringBuilder();
423	        csv.append("reservation,room,check_in,check_out,status,amount\n");
424	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
425	        for (Reservation reservation : withRevenue) {
426	            csv.append(reservation.id()).append(',')
427	                    .append(reservation.roomNumber()).append(',')
428	                    .append(reservation.checkIn()).append(',')
429	                    .append(reservation.checkOut()).append(',')
430	                    .append(reservation.status()).append(',')
431	                    .append(reservation.amountKept().toPlainString()).append('\n');
432	            revenue = revenue.add(reservation.amountKept());
433	        }
434	        csv.append("total,").append(revenue.toPlainString()).append('\n');
435	        return csv.toString();
436	    }
437	}
